import { z } from 'zod';
import type { ObjectStore } from '@eventhub/kernel';
import type { EventConsumer } from './consumer.ts';

export const ASSET_DELETED = 'asset.deleted';

const payload = z.object({
  assetId: z.uuid(),
  // Server-generated by the API (ADR-0042); checked again here so a malformed event cannot reach
  // outside the asset's own prefix.
  storageKey: z.string().regex(/^organizations\/[0-9a-f-]{36}\/assets\/[0-9a-f-]{36}$/),
});

/**
 * Removes the stored renditions of a deleted image (ADR-0042). Deleting a missing object
 * succeeds, so a retry after a partial failure finishes the job. The key must belong to the
 * event's own organization and asset.
 */
export function deleteAssetObjectsConsumer(store: ObjectStore): EventConsumer {
  return {
    name: 'asset.delete_objects',
    eventTypes: [ASSET_DELETED],
    async handle(event) {
      const p = payload.parse(event.payload);
      if (!event.organizationId) return;
      if (p.storageKey !== `organizations/${event.organizationId}/assets/${p.assetId}`) {
        throw new Error('asset.deleted: storage key does not match the asset');
      }
      for (const variant of ['large', 'small']) {
        await store.delete(`${p.storageKey}/${variant}.webp`);
      }
    },
  };
}
